package com.tekwatt.reservation.repository;import com.tekwatt.reservation.entity.*;import java.time.Instant;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface ReservationRepository extends JpaRepository<Reservation,UUID>{boolean existsByReference(String reference);List<Reservation>findAllByTenantIdOrderByStartsAtDesc(UUID tenantId);@Query("select (count(r)>0) from Reservation r where r.connectorId=:connectorId and r.status=com.tekwatt.reservation.entity.ReservationStatus.ACTIVE and r.startsAt<:expiresAt and r.expiresAt>:startsAt")boolean hasConflict(@Param("connectorId")UUID connectorId,@Param("startsAt")Instant startsAt,@Param("expiresAt")Instant expiresAt);}
